package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.workflow.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.assertEquals;
class ParallelNodeExecutorTest {@Test void returnsEveryDeclaredBranchInPriorityOrder(){WorkflowNodeDefinition node=NodeExecutorTestSupport.node("parallel",WorkflowNodeType.PARALLEL,"{}");List<WorkflowEdgeDefinition> edges=Arrays.asList(NodeExecutorTestSupport.edge("parallel","first",null,20,null),NodeExecutorTestSupport.edge("parallel","second",null,10,null));NodeExecutionResult result=new ParallelNodeExecutor(new ObjectMapper()).execute(NodeExecutorTestSupport.context(node,new HashMap<>(),edges));assertEquals(Arrays.asList("first","second"),result.getNextNodeIds());}}
